(* [comment removed for export] *)
Definition chx_out (E0 E' : ecv) : Prop :=
  E' = E0
  \/ (ec_cat E' = G_HTTP_CAT /\ (ec_val E' = HE_NEED_MORE \/ ec_val E' = HE_BAD_CHUNK_EXTENSION)
      /\ 2 <= ec_flags E' /\ Z.odd (ec_flags E') = true /\ ec_ok E').

(* [comment removed for export] *)
Definition CHX_STACK : Z := 128.

Section HCW.
  Context {HCEIL : HeapCeil}.

Definition chx_W (lo : Z) (sp : word) (I E : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (I, I + 8); (E, E + 24); (G_HTTP_CAT, G_HTTP_CAT + 64)]%Z.

Definition chx_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (it0 I E lo : Z) (bs : list byte) (E0 : ecv) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' it' E' g',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch (chx_W lo sp I E) m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ bytes_at usegs m' it0 bs
    /\ rw_cells usegs m' I [C8 (wz it')] /\ it0 <= it' <= it0 + Z.of_nat (length bs)
    /\ rw_cells usegs m' E (ErrCodeCells E') /\ chx_out E0 E'
    /\ HttpCat m' g' /\ XStatics m'.

Definition chx_pure (sp : word) (it0 I E lo : Z) (bs : list byte) (E0 : ecv) : Prop :=
  ec_ok E0 /\ lo + CHX_STACK <= bv_unsigned sp /\ 0xb8000 <= lo /\ ((0 < it0 /\ it0 + Z.of_nat (length bs) <= 0x10000) \/ 0x95090 <= it0) /\ it0 + Z.of_nat (length bs) <= lo
  /\ bv_unsigned sp <= I /\ I + 8 <= 2^64 /\ bv_unsigned sp <= E /\ E + 24 <= 2^64 /\ (I + 8 <= E \/ E + 24 <= I).

Definition chx_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (it0 I E lo : Z) (bs : list byte) (E0 : ecv) (g : bool),
  bytes_at usegs m it0 bs ->
  rw_cells usegs m I [C8 (wz it0)] ->
  rw_cells usegs m E (ErrCodeCells E0) ->
  HttpCat m g -> XStatics m ->
  stk usegs m lo (bv_unsigned sp) ->
  chx_pure sp it0 I E lo bs E0 ->
  mem_inv usegs m ->
  evt usegs (chx_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc it0 I E lo bs E0 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz I) (wz (it0 + Z.of_nat (length bs))) (wz E) a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BP_PARSE_CHUNK_EXT) fc None m (seg_rom usegs)).

(* [comment removed for export] *)
(* [comment removed for export] *)

(* [comment removed for export] *)
Definition chx_ctx (m m1 : mem) (sp : word) (sv : list word) (s0v rav : word) (it0 I E lo : Z) (bs : list byte) (itv : Z) (E0 : ecv) (g : bool)
    (j8 : list byte) (tmp : list cell) : Prop :=
  rw_cells usegs m1 (bv_unsigned sp + -96) [CB 8 j8]
  /\ rw_cells usegs m1 (bv_unsigned sp + -88) tmp
  /\ rw_cells usegs m1 (bv_unsigned sp + -64) (map C8 sv ++ [C8 s0v; C8 rav])
  /\ rw_cells usegs m1 I [C8 (wz itv)]
  /\ rw_cells usegs m1 E (ErrCodeCells E0)
  /\ HttpCat m1 g /\ XStatics m1
  /\ stk usegs m1 lo (bv_unsigned sp + -96)
  /\ bytes_at usegs m1 it0 bs
  /\ munch (chx_W lo sp I E) m m1 /\ wmono usegs m m1 /\ mem_inv usegs m1.

Local Ltac open_chx CTX PURE :=
  destruct CTX as (FR0 & TMP & FRhi & IT & EC & HC & XS & ST & WIN & MU & WM & MI);
  destruct PURE as (EOK & LO & IMG & QLO & QHI & ILO & IHI & ELO & EHI & DIE);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  unfold ErrCodeCells in EC; cbn [map app] in FRhi;
  unfold chx_W, G_HTTP_CAT, CHX_STACK in *.

(* [comment removed for export] *)
Definition chx_regs (rax spv gp tp : word) (I L E : Z) (y1 y2 y3 y4 y5 y6 s7 s8 s9 s10 s11 x3 x4 x5 x6 : word) :=
  mkR rax spv gp tp (Z_to_bv 64 (-1)) (wz 34) (wz 92) (wz E) y1 (wz I) (wz L) (wz 9) (wz 1) (wz 32) (wz 59) (wz 2) (wz 61)
      y2 y3 y4 y5 y6 s7 s8 s9 s10 s11 x3 x4 x5 x6.

