(* [comment removed for export] *)
Definition chx_exitB_stmt (pc e : Z) : Prop :=
  forall rax ra sp gp tp q0 q1 q2 y1 qa0 qa1 qa2 qa3 qa4 qa5 qa6 qa7 y2 y3 y4 y5 y6 s7 s8 s9 s10 s11 x3 x4 x5 x6
    (sv1 sv2 sv3 sv4 sv5 sv6 s0v : word)
    (F : bvmap 5 word) fc (m m1 : mem) (it0 I E lo : Z) (bs : list byte) (itv : Z) (E0 : ecv) (g : bool) (j8 junk : list byte),
  chx_ctx m m1 sp [sv6; sv5; sv4; sv3; sv2; sv1] s0v ra it0 I E lo bs itv E0 g j8 [CB 24 junk] -> chx_pure sp it0 I E lo bs E0 ->
  it0 <= itv <= it0 + Z.of_nat (length bs) ->
  evt usegs (chx_post ra sp gp tp s0v sv1 sv2 sv3 sv4 sv5 sv6 s7 s8 s9 s10 s11 F fc it0 I E lo bs E0 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -96)) gp tp q0 q1 q2 (wz E) y1 qa0 qa1 qa2 qa3 qa4 qa5 qa6 qa7
              y2 y3 y4 y5 y6 s7 s8 s9 s10 s11 x3 x4 x5 x6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom usegs)).

Local Ltac chx_exitB_script e :=
  intros rax ra sp gp tp q0 q1 q2 y1 qa0 qa1 qa2 qa3 qa4 qa5 qa6 qa7 y2 y3 y4 y5 y6 s7 s8 s9 s10 s11 x3 x4 x5 x6
         sv1 sv2 sv3 sv4 sv5 sv6 s0v F fc m m1 it0 I E lo bs itv E0 g j8 junk;
  intros CTX PURE ITV;
  destruct CTX as (FR0 & TMP & FRhi & IT & EC & HC & XS & ST & WIN & MU & WM & MI);
  destruct PURE as (EOK & LO & IMG & QLO & QHI & ILO & IHI & ELO & EHI & DIE);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  cbn [map app] in FRhi; unfold chx_W, G_HTTP_CAT, CHX_STACK in *; unfold wz in *;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  (* [comment removed for export] *)
  steps_to 0x407f4%Z;
  join_frame TMP FRhi (bv_unsigned sp + -88); join_frame FR0 TMP (bv_unsigned sp + -96);
  (* [comment removed for export] *)
  step; release_frame FR0 ST (bv_unsigned sp); step;
  destruct (rw_cells_forget _ _ _ _ EC) as [junkE EC']; cbn [cells_size csize Nat.add ErrCodeCells] in EC'; clear EC;
  let AS := fresh "AS" in
  pose proof assignB_spec as AS; unfold assignB_stmt, assign_stmt, assign_post, assign_W, P_EC_ASSIGN_HTTP, G_HTTP_CAT in AS;
  callZ (AS _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ E e lo g junkE);
  [ exact EC' | exact HC | exact XS | exact ST | lia | lia | lia | lia | lia | exact MI | clear AS ];
  lazymatch goal with XS' : XStatics ?mx, HC' : HttpCat ?mx true |- _ =>
    chx_finish itv (EC_http e) true;
    right; unfold EC_http, ec_make, ec_ok, HE_NEED_MORE, HE_BAD_CHUNK_EXTENSION, G_HTTP_CAT;
    cbn [ec_val ec_cat ec_flags Z.eqb]; repeat split; try lia; reflexivity
  end.

