(* [comment removed for export] *)
Definition cut_pc (c : nat) : Z :=
  match c with 0%nat => 0x404b8 | 1%nat => 0x404d8 | 2%nat => 0x40500 | 3%nat => 0x40518 | 4%nat => 0x40564
             | 5%nat => 0x405a0 | 6%nat => 0x405f4 | 7%nat => 0x40620 | _ => 0x406a4 end.
Definition cut_rank (c : nat) : Z :=
  match c with 0%nat => 2 | 1%nat => 1 | 2%nat => 0 | 3%nat => 1 | 4%nat => 0 | 5%nat => 0 | 6%nat => 1 | 7%nat => 0 | _ => 0 end.

Definition TABw : word := wz U_TAB_TCHAR.
(* [comment removed for export] *)
Definition NTABw : word := wz 18446744073709463757.

Definition cut_y1 (c : nat) (p : Z) (y : word) : word := match c with 3%nat | 4%nat => wz (p + 1) | 6%nat | 8%nat => wz p | _ => y end.
Definition cut_y2 (c : nat) (p : Z) (y : word) : word := match c with 3%nat | 4%nat => wz (p + 1) | _ => y end.
Definition cut_y3 (c : nat) (p : Z) (y : word) : word := match c with 3%nat | 4%nat => wz (p + 2) | _ => y end.
Definition cut_y4 (c : nat) (p : Z) (y : word) : word := match c with 5%nat => wz p | _ => y end.
Definition cut_x3 (c : nat) (p : Z) (x : word) : word :=
  match c with 0%nat | 2%nat | 3%nat => wz p | 1%nat | 5%nat | 6%nat | 8%nat => wz (p + 1) | _ => x end.
Definition cut_x4 (c : nat) (p : Z) (x : word) : word := match c with 1%nat => wz p | 4%nat | 5%nat | 6%nat | 8%nat => TABw | _ => x end.
Definition cut_x5 (c : nat) (x : word) : word := match c with 4%nat | 5%nat | 6%nat => NTABw | _ => x end.
Definition cut_x6 (c : nat) (p : Z) (x : word) : word := match c with 3%nat | 4%nat | 6%nat | 7%nat => wz p | _ => x end.
Definition cut_known (c : nat) : bool := match c with 0%nat | 1%nat | 6%nat => true | _ => false end.

Definition cut_side (c : nat) (p itv it0 L : Z) : Prop :=
